import React from 'react';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/shared/ui/select";

// Lista padronizada das lojas da rede (Fábrica + 5 lojas físicas)
export const STORES = [
  { value: "FABRICA", label: "Fábrica" },
  { value: "ASA SUL", label: "Asa Sul" },
  { value: "ASA NORTE", label: "Asa Norte" },
  { value: "LAGO SUL", label: "Lago Sul" },
  { value: "AGUAS CLARAS", label: "Águas Claras" },
  { value: "BRASILIA SHOPPING", label: "Brasília Shopping" }
] as const;

export type StoreValue = typeof STORES[number]['value'];

interface StoreSelectorProps {
  value?: string;
  onValueChange: (value: string) => void;
  placeholder?: string;
  disabled?: boolean;
  className?: string;
}

export const StoreSelector: React.FC<StoreSelectorProps> = ({
  value,
  onValueChange,
  placeholder = "Selecione uma loja",
  disabled = false,
  className = ""
}) => {
  return (
    <Select value={value} onValueChange={onValueChange} disabled={disabled}>
      <SelectTrigger
        className={className}
        data-mia-filter="loja"
        data-mia-options={STORES.map((s) => s.value).join(',')}
        data-mia-description="Seletor global de loja (Fábrica, Asa Sul, Asa Norte, Lago Sul, Águas Claras, Brasília Shopping)"
      >
        <SelectValue placeholder={placeholder} />
      </SelectTrigger>
      <SelectContent>
        {STORES.map((store) => (
          <SelectItem
            key={store.value}
            value={store.value}
            data-mia-option-value={store.value}
            data-mia-option-label={store.label}
          >
            {store.label}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
};

// Função utilitária para normalizar nomes de lojas
export const normalizeStoreName = (storeName: string): StoreValue | null => {
  const normalized = storeName.toUpperCase().trim();

  // Mapeamento de variações para valores padronizados
  const storeMapping: Record<string, StoreValue> = {
    'FABRICA': 'FABRICA',
    'FÁBRICA': 'FABRICA',
    'MOMMA FABRICA': 'FABRICA',
    'MOMMA FÁBRICA': 'FABRICA',
    'ASA SUL': 'ASA SUL',
    'ASASUL': 'ASA SUL',
    'ASA_SUL': 'ASA SUL',
    'MOMMA ASA SUL': 'ASA SUL',
    'ASA NORTE': 'ASA NORTE',
    'ASANORTE': 'ASA NORTE',
    'ASA_NORTE': 'ASA NORTE',
    'MOMMA ASA NORTE': 'ASA NORTE',
    'LAGO SUL': 'LAGO SUL',
    'MOMMA LAGO SUL': 'LAGO SUL',
    'LAGOSUL': 'LAGO SUL',
    'LAGO_SUL': 'LAGO SUL',
    'LAGO': 'LAGO SUL',
    'AGUAS CLARAS': 'AGUAS CLARAS',
    'ÁGUAS CLARAS': 'AGUAS CLARAS',
    'MOMMA AGUAS CLARAS': 'AGUAS CLARAS',
    'MOMMA ÁGUAS CLARAS': 'AGUAS CLARAS',
    'AGUAS_CLARAS': 'AGUAS CLARAS',
    'AGUASCLARAS': 'AGUAS CLARAS',
    'BRASILIA SHOPPING': 'BRASILIA SHOPPING',
    'BRASÍLIA SHOPPING': 'BRASILIA SHOPPING',
    'MOMMA BRASILIA SHOPPING': 'BRASILIA SHOPPING',
    'MOMMA BRASÍLIA SHOPPING': 'BRASILIA SHOPPING',
    'BRASILIA_SHOPPING': 'BRASILIA SHOPPING',
    'BRASILIASHOPPING': 'BRASILIA SHOPPING'
  };

  return storeMapping[normalized] || null;
};

// Função para obter o label de uma loja pelo valor
export const getStoreLabel = (value: string): string => {
  const store = STORES.find(s => s.value === value);
  return store?.label || value;
};

